<template>
  <view class="page">
    <view v-if="loading" class="detail-loading"><view class="detail-skeleton hero-skeleton" /><view class="detail-skeleton card-skeleton" /><view class="detail-skeleton card-skeleton short" /></view>
    <view v-else-if="loadError" class="state-card error-state"><text class="state-icon">!</text><text class="state-title">发布任务加载失败</text><text class="state-copy">{{ loadError }}</text><view class="state-actions"><button class="retry-button" @click="initialize">重试</button><button class="back-button" @click="backToPublisher">返回发布中心</button></view></view>
    <template v-else-if="task">
      <view class="hero">
        <view class="hero-top"><text class="eyebrow">发布管理</text><text class="status">{{ statusText(task.status) }}</text></view>
        <text class="title">{{ task.title }}</text>
        <text class="description">{{ task.description || '暂无任务说明' }}</text>
        <view class="metrics"><view><strong>{{ task.historical_claim_count || 0 }}</strong><small>累计领取</small></view><view><strong>{{ task.active_reservation_count || 0 }}</strong><small>进行中</small></view><view><strong>{{ task.successful_reward_count || 0 }}</strong><small>已结算</small></view><view><strong>{{ task.remaining_reward_slots ?? task.reward_quota_total ?? 0 }}</strong><small>剩余名额</small></view></view>
      </view>

      <view class="panel flow-panel"><view class="panel-head"><text>发布闭环</text><text>状态可追溯</text></view><view class="flow-track"><view v-for="(item,index) in workflowStages" :key="item" :class="['flow-node',{current:index===workflowIndex,done:index<workflowIndex}]"><text>{{ index < workflowIndex ? '✓' : index + 1 }}</text><small>{{ item }}</small></view></view><text class="flow-note">当前处于：{{ currentFlowLabel }}。领取记录、提交材料与奖励验收均保留在任务快照中。</text></view>

      <view class="tool-row"><button class="tool-button" :disabled="actionWorking" @click="loadVersions">版本快照</button><button class="tool-button" :disabled="actionWorking" @click="loadAudit">审核轨迹</button></view>
      <view v-if="historyMode==='versions'" class="panel history-panel"><view class="panel-head"><text>版本快照</text><text>不可覆盖历史版本</text></view><text v-if="historyError" class="history-error">{{ historyError }}</text><view v-for="item in versions" :key="item.version_no" class="history-row"><view><text class="step-title">v{{ item.version_no }} · {{ versionStatusText(item.status) }}</text><text class="muted">{{ changeTypeText(item.change_type) }} · {{ (item.changed_fields||[]).join('、') || '无字段变化' }}</text></view><text class="history-time">{{ formatTime(item.created_at) }}</text></view><view v-if="!versions.length && !historyError" class="empty">暂无版本记录</view></view>
      <view v-if="historyMode==='audit'" class="panel history-panel"><view class="panel-head"><text>审核轨迹</text><text>仅当前发布身份可见</text></view><text v-if="historyError" class="history-error">{{ historyError }}</text><view v-for="item in auditRows" :key="item.id" class="history-row"><view><text class="step-title">{{ auditActionText(item.action) }}</text><text class="muted">{{ item.reason || '未填写原因' }} · {{ item.actor || '任务发布管理员' }}</text></view><text class="history-time">{{ formatTime(item.created_at) }}</text></view><view v-if="!auditRows.length && !historyError" class="empty">暂无轨迹记录</view></view>

      <view v-if="task.publish_approval" class="panel approval"><view class="panel-head"><text>发布审核</text><text>{{ approvalText(task.publish_approval.status) }}</text></view><text v-if="task.publish_approval.review_note" class="muted">审核说明：{{ task.publish_approval.review_note }}</text><text v-if="task.publish_approval.triggered_rules?.length" class="muted">触发规则：{{ task.publish_approval.triggered_rules.join('、') }}</text></view>

      <view v-if="task.has_unpublished_changes" class="panel draft-notice"><text class="panel-title">待发布版本</text><text class="muted">当前任务已有未发布编辑版本，线上用户继续使用 v{{ task.current_published_version || '—' }} 快照。</text></view>

      <view class="panel"><text class="panel-title">任务时限</text><view class="info-row"><text>领取截止</text><text>{{ formatTime(task.claim_ends_at) }}</text></view><view class="info-row"><text>提交截止</text><text>{{ formatTime(task.submit_ends_at) }}</text></view><view class="info-row"><text>完成时限</text><text>{{ task.completion_window_hours || 0 }} 小时</text></view><view class="info-row"><text>审核时限</text><text>{{ task.review_deadline_hours || 0 }} 小时</text></view></view>

      <view class="panel"><text class="panel-title">任务步骤</text><view v-for="(step,index) in task.steps || []" :key="step.id" class="step-row"><text class="step-index">{{ index + 1 }}</text><view><text class="step-title">{{ step.title }}</text><text class="muted">{{ step.description }}</text></view></view><view v-if="!task.steps?.length" class="empty">暂无步骤配置</view></view>

      <view class="panel"><text class="panel-title">奖励预算</text><view v-for="(budget,index) in task.reward_budgets || []" :key="index" class="budget"><view><text class="step-title">{{ assetText(budget.asset_type) }}</text><text class="muted">已发放 {{ amountText(budget.asset_type,budget.issued_amount) }} · 已预留 {{ amountText(budget.asset_type,budget.reserved_amount) }}</text></view><text class="budget-value">可用 {{ amountText(budget.asset_type,budget.available_amount) }}</text></view></view>

      <view class="panel action-panel"><text class="panel-title">任务管理</text><text class="muted">状态操作需要说明原因，结束任务时会按规则处理已领取记录并释放未占用预算。</text><view class="actions"><button v-if="task.status==='draft'" class="primary" :disabled="actionWorking" @click="change('publish')">申请发布</button><button v-if="['published','scheduled','paused','pending_approval'].includes(task.status)" class="secondary" :disabled="actionWorking" @click="editTask">编辑</button><button v-if="['published','scheduled'].includes(task.status)" class="secondary" :disabled="actionWorking" @click="change('pause')">暂停发布</button><button v-if="task.status==='paused'" class="primary" :disabled="actionWorking" @click="change('resume')">恢复发布</button><button v-if="!['closed','archived'].includes(task.status)" class="danger" :disabled="actionWorking" @click="change('close')">结束任务</button></view></view>
    </template>
    <view v-else class="state-card empty-state"><text class="state-icon">档</text><text class="state-title">任务不存在或已下线</text><text class="state-copy">请返回发布中心重新选择任务，发布身份过期时需要重新验证。</text><button class="back-button" @click="backToPublisher">返回发布中心</button></view>
  </view>
</template>

<script setup lang="ts">
import { formatDateTime } from '@/utils/dateTime'
import { computed, ref } from 'vue'
import { onLoad, onShow } from '@dcloudio/uni-app'
import { changePublisherTaskStatus, createMyPublisherSession, getPublisherTask, listPublisherTaskAudit, listPublisherTaskVersions, type PublisherAuditEvent, type PublisherTask, type PublisherTaskVersion } from '@/api/publisher'
import { useAuthStore } from '@/stores/auth'
import { navigateToLogin } from '@/utils/authRedirect'
import { clearPublisherSession, isPublisherAccessError, persistPublisherSession, readPublisherSession } from '@/utils/publisherSession'

const auth=useAuthStore()
const task=ref<PublisherTask|null>(null);const loading=ref(true);const loadError=ref('');const actionWorking=ref(false);const historyError=ref('');const historyMode=ref<'versions'|'audit'|''>('');const versions=ref<PublisherTaskVersion[]>([]);const auditRows=ref<PublisherAuditEvent[]>([]);let taskId='';let token=''
let initializing=false;let leavingForAccess=false
const workflowStages=['草稿','审核','发布','领取','验收']
const workflowIndex=computed(()=>{if(!task.value)return 0;if((task.value.successful_reward_count||0)>0)return 4;if((task.value.active_reservation_count||0)>0)return 3;if(['published','scheduled','paused','closed','archived'].includes(task.value.status))return 2;if(task.value.status==='pending_approval')return 1;return 0})
const currentFlowLabel=computed(()=>workflowStages[workflowIndex.value])
onLoad((options)=>{taskId=String(options?.id||'')})
onShow(()=>{void initialize()})
async function initialize(){
  if(initializing||leavingForAccess)return
  initializing=true;loading.value=true;loadError.value=''
  try{
    if(!auth.isAuthenticated){clearPublisherSession();navigateToLogin(detailReturnUrl());return}
    await auth.fetchCurrentUser()
    if(!auth.isAuthenticated){clearPublisherSession();navigateToLogin(detailReturnUrl());return}
    if(auth.user?.can_publish_tasks!==true){await exitForAccess('当前账号暂无任务发布权限。');return}
    const saved=readPublisherSession(auth.user.id)
    if(saved)token=saved.token
    else{const session=await createMyPublisherSession(auth.accessToken);token=session.access_token;persistPublisherSession(session,auth.user.id)}
    await load()
  }catch(error){if(!handlePublisherAccessError(error))loadError.value=error instanceof Error?error.message:'请检查网络后重试'}
  finally{loading.value=false;initializing=false}
}
async function load(){loading.value=true;loadError.value='';try{if(!token||!taskId)throw new Error('请先返回发布中心验证身份');task.value=await getPublisherTask(token,taskId)}catch(error){task.value=null;if(!handlePublisherAccessError(error))loadError.value=error instanceof Error?error.message:'请检查网络后重试'}finally{loading.value=false}}
function detailReturnUrl(){return `/pages/publisher-task-detail/index?id=${encodeURIComponent(taskId)}`}
async function exitForAccess(message:string){if(leavingForAccess)return;leavingForAccess=true;clearPublisherSession();token='';task.value=null;await uni.showModal({title:'无法管理发布任务',content:message,showCancel:false,confirmText:'返回我的'});uni.reLaunch({url:'/pages/account/index'})}
function handlePublisherAccessError(error:unknown){if(!isPublisherAccessError(error))return false;void exitForAccess(error instanceof Error?error.message:'发布身份已失效，请重新进入。');return true}
function backToPublisher(){const pages=getCurrentPages();const previous=pages[pages.length-2] as {route?:string}|undefined;const previousRoute=String(previous?.route||'');if(previousRoute==='pages/publisher/index'||previousRoute==='/pages/publisher/index'){uni.navigateBack({delta:1});return}uni.redirectTo({url:'/pages/publisher/index'})}
async function change(action:'publish'|'pause'|'resume'|'close'){const labels={publish:'申请发布',pause:'暂停发布',resume:'恢复发布',close:'结束任务'};uni.showModal({title:labels[action],editable:true,placeholderText:'请输入本次操作原因',content:`发布方${labels[action]}`,success:async result=>{if(!result.confirm)return;const reason=(result.content||'').trim();if(!reason)return uni.showToast({title:'请填写操作原因',icon:'none'});actionWorking.value=true;try{task.value=await changePublisherTaskStatus(token,taskId,action,reason,action==='close'?'continue':undefined);historyMode.value='';uni.showToast({title:'状态已更新',icon:'success'})}catch(error){if(!handlePublisherAccessError(error))uni.showToast({title:error instanceof Error?error.message:'操作失败',icon:'none'})}finally{actionWorking.value=false}}})}
function editTask(){uni.navigateTo({url:`/pages/publisher/index?edit=${encodeURIComponent(taskId)}`})}
async function loadVersions(){historyError.value='';try{versions.value=await listPublisherTaskVersions(token,taskId);historyMode.value='versions'}catch(error){if(handlePublisherAccessError(error))return;historyError.value=error instanceof Error?error.message:'版本读取失败';uni.showToast({title:historyError.value,icon:'none'})}}
async function loadAudit(){historyError.value='';try{auditRows.value=(await listPublisherTaskAudit(token,taskId)).items;historyMode.value='audit'}catch(error){if(handlePublisherAccessError(error))return;historyError.value=error instanceof Error?error.message:'审核轨迹读取失败';uni.showToast({title:historyError.value,icon:'none'})}}
function formatTime(value?: string | null) { return formatDateTime(value, '未设置') }
function statusText(value:string){return({draft:'草稿',pending_approval:'待财务复核',published:'已发布',scheduled:'已排期',paused:'已暂停',closed:'已结束',archived:'已归档'} as Record<string,string>)[value]||'状态待同步'}
function approvalText(value:string){return({pending:'待审核',approved:'已通过',rejected:'已驳回'} as Record<string,string>)[value]||'待平台确认'}
function assetText(value:string){return value==='points'?'积分奖励':value==='wallet_cash'?'余额奖励':'优惠券奖励'}
function amountText(type:string,value:number){return type==='points'?`${value} 积分`:`¥${(value/100).toFixed(2)}`}
function versionStatusText(value:string){return({draft:'编辑草稿',pending_approval:'待复核',approved:'已通过',published:'已发布',rejected:'已驳回',superseded:'已替代'} as Record<string,string>)[value]||'版本状态待同步'}
function changeTypeText(value:string){return({initial:'初始版本',minor:'小幅编辑',major:'关键字段调整',rollback:'回滚生成'} as Record<string,string>)[value]||'版本更新'}
function auditActionText(value:string){return({'task.create_draft':'创建任务草稿','task.create_version':'编辑并生成新版本','task.publisher_create_version':'编辑并生成新版本','task.publish':'发布任务','task.publisher_publish':'申请发布','task.pause':'暂停发布','task.publisher_pause':'暂停发布','task.resume':'恢复发布','task.publisher_resume':'恢复发布','task.close':'结束任务','task.publisher_close':'结束任务','task.archive':'归档任务','task.publisher_archive':'归档任务','task.publish_approval.approve':'财务复核通过','task.publish_approval.reject':'财务复核驳回'} as Record<string,string>)[value]||'平台操作'}
</script>

<style scoped>
.page{min-height:100vh;padding:24rpx 24rpx 120rpx;box-sizing:border-box;background:var(--tm-canvas)}.hero,.panel,.state-card{border:1rpx solid var(--tm-line);border-radius:30rpx;background:#fff;box-shadow:var(--tm-shadow-card)}.hero{padding:30rpx;color:#fff;background:linear-gradient(145deg,#0e695f,#16887b)}.hero-top,.panel-head,.info-row,.budget{display:flex;align-items:center;justify-content:space-between}.eyebrow{font-size:13px;letter-spacing:3rpx;opacity:.75}.status{padding:8rpx 14rpx;border-radius:999rpx;background:rgba(255,255,255,.18);font-size:13px}.title{display:block;margin-top:18rpx;font-size:22px;font-weight:850}.description{display:block;margin-top:10rpx;color:rgba(255,255,255,.78);font-size:14px;line-height:1.6}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:6rpx;margin-top:28rpx}.metrics view{text-align:center}.metrics strong,.metrics small{display:block}.metrics strong{font-size:17px}.metrics small{margin-top:5rpx;font-size:12px;opacity:.7}.tool-row{display:grid;grid-template-columns:1fr 1fr;gap:14rpx;margin-top:18rpx}.tool-button{height:64rpx;margin:0;border:1rpx solid var(--tm-line);border-radius:16rpx;background:#fff;color:var(--tm-brand-700);font-size:14px;line-height:64rpx}.tool-button::after{border:0}.panel,.state-card{margin-top:20rpx;padding:26rpx}.panel-title,.panel-head text:first-child{font-size:17px;font-weight:850}.approval{background:#fffaf0}.draft-notice{background:#effaf5}.panel-head text:last-child{color:#b36b00;font-size:14px;font-weight:750}.history-row{display:flex;align-items:flex-start;justify-content:space-between;gap:14rpx;padding:18rpx 0;border-bottom:1rpx solid #edf1f5}.history-row:last-child{border-bottom:0}.history-time{flex:none;color:#98a2b3;font-size:12px}.info-row{padding:18rpx 0;border-bottom:1rpx solid #edf1f5;font-size:14px}.info-row text:last-child{color:#667085}.step-row{display:flex;gap:18rpx;padding:20rpx 0;border-bottom:1rpx solid #edf1f5}.step-index{display:flex;align-items:center;justify-content:center;width:48rpx;height:48rpx;flex:none;border-radius:16rpx;background:var(--tm-brand-100);color:var(--tm-brand-700);font-size:13px;font-weight:850}.step-title{display:block;font-size:14px;font-weight:800}.muted,.empty{display:block;margin-top:7rpx;color:#7c8798;font-size:13px;line-height:1.55}.budget{padding:20rpx 0;border-bottom:1rpx solid #edf1f5}.budget-value{color:#0e746a;font-size:14px;font-weight:800}.actions{display:grid;grid-template-columns:repeat(2,1fr);gap:14rpx;margin-top:22rpx}.actions button{height:72rpx;margin:0;border-radius:18rpx;font-size:14px;line-height:72rpx}.actions button::after{border:0}.primary{background:var(--tm-brand-600);color:#fff}.secondary{border:1rpx solid var(--tm-line)!important;background:#f5f8fa;color:#314055}.danger{border:1rpx solid #f2c2bd!important;background:#fff5f4;color:#b42318}.state-card{text-align:center;color:#7c8798;font-size:14px}
.page{background:radial-gradient(circle at 94% 1%,rgba(59,207,214,.18),transparent 27%),linear-gradient(180deg,#eefaff 0,#f7fbfd 42%,#f4f8fa 100%)!important}.hero{border:1rpx solid #d7e8ef!important;background:linear-gradient(135deg,#1268c9,#1aaec1)!important;box-shadow:0 16rpx 34rpx rgba(29,104,145,.16)!important}.panel,.state-card{border:1rpx solid #dce9ef!important;box-shadow:0 12rpx 30rpx rgba(34,78,103,.075)!important;background:rgba(255,255,255,.97)!important}.tool-button{border:1rpx solid #cfe1e9!important;background:#fff!important;box-shadow:none!important}.tool-button[disabled]{opacity:.5}.approval{background:#fff8e8!important;border-color:#f0dfb2!important}.draft-notice{background:#effaf7!important;border-color:#c9eadc!important}.step-index{border:0!important;background:linear-gradient(145deg,#1268dc,#20b9c8)!important;color:#fff!important;box-shadow:0 7rpx 16rpx rgba(18,104,220,.16)!important}.actions button{border:1rpx solid #d3e2e9!important;box-shadow:none!important}.actions .primary{border:0!important;background:linear-gradient(135deg,#1268c9,#19a7c8)!important;box-shadow:0 8rpx 18rpx rgba(18,104,201,.16)!important}.actions .danger{background:#fff4f2!important;color:#b9382d!important;border-color:#f0c8c1!important}.actions button[disabled]{opacity:.5;box-shadow:none!important}.detail-loading{padding-top:10rpx}.detail-skeleton{border-radius:28rpx;background:linear-gradient(100deg,#e6f1f5 30%,#f8fcfd 45%,#e6f1f5 60%);background-size:220% 100%;animation:publisher-detail-shimmer 1.2s ease-in-out infinite}.hero-skeleton{height:310rpx}.card-skeleton{height:220rpx;margin-top:20rpx}.card-skeleton.short{height:150rpx}.error-state,.empty-state{display:flex;align-items:center;flex-direction:column;text-align:center}.state-icon{display:flex;align-items:center;justify-content:center;width:64rpx;height:64rpx;border-radius:20rpx;background:#e8f7fb;color:#1477c7;font-size:15px;font-weight:900}.state-title{margin-top:14rpx;color:#173b53;font-size:15px;font-weight:850}.state-copy{margin-top:8rpx;color:#7a909e;font-size:13px;line-height:1.55}.retry-button{height:60rpx;margin-top:20rpx;padding:0 26rpx;border:1rpx solid #b9dbe5;border-radius:999rpx;background:#fff;color:#1475c5;font-size:14px;line-height:58rpx}.retry-button::after{border:0}.flow-panel{background:linear-gradient(145deg,#fff,#f1fbfd)!important}.flow-track{display:flex;justify-content:space-between;gap:6rpx;margin-top:22rpx}.flow-node{position:relative;display:flex;align-items:center;flex-direction:column;gap:7rpx;min-width:0;flex:1;color:#91a2ad;font-size:12px}.flow-node:not(:last-child)::after{content:'';position:absolute;left:58%;top:19rpx;width:84%;height:2rpx;background:#dce9ef}.flow-node text{position:relative;z-index:1;display:flex;align-items:center;justify-content:center;width:40rpx;height:40rpx;border-radius:50%;background:#eef4f7;color:#80939e;font-size:12px;font-weight:850}.flow-node.done,.flow-node.current{color:#1475c5;font-weight:800}.flow-node.done text{background:#dcf8e9;color:#087a4d}.flow-node.current text{background:#1778ce;color:#fff;box-shadow:0 6rpx 14rpx rgba(23,120,206,.18)}.flow-node.done:not(:last-child)::after{background:#a9dec6}.flow-note{display:block;margin-top:17rpx;padding:13rpx 15rpx;border-radius:15rpx;background:#eef9fc;color:#668594;font-size:13px;line-height:1.5}.history-error{display:block;margin-top:14rpx;padding:12rpx 14rpx;border-radius:14rpx;background:#fff2ef;color:#b9382d;font-size:13px}
@keyframes publisher-detail-shimmer{0%{background-position:100% 0}100%{background-position:-100% 0}}
.state-actions{display:flex;justify-content:center;gap:12rpx;margin-top:20rpx}.state-actions button{margin-top:0}.back-button{height:60rpx;padding:0 26rpx;border:1rpx solid #cfe1e9;border-radius:999rpx;background:#fff;color:#1475c5;font-size:14px;line-height:58rpx}.back-button::after{border:0}
</style>
